// Akıllı sera: sıcaklık, hava nemi ve toprak nemini ölç; toprak kuruyunca pompayı çalıştır.
// OLED durumu gösterir. Web sayfası değerleri verir ve "Sula" düğmesiyle elle sulatır.
#include <WiFi.h>
#include <WebServer.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <DHT.h>

const char* AG_ADI = "EvimWiFi";     // kendi Wi-Fi ağının adı
const char* PAROLA = "parola123";    // kendi Wi-Fi parolan

const int DHT_PIN = 4;      // DHT22 SDA
const int TOPRAK_PIN = 32;  // toprak nem sensörü AO (ADC1: Wi-Fi açıkken çalışır)
const int ROLE_PIN = 26;    // röle modülü IN

// Toprak sensörü ayarı: sensör havadayken ve sudayken seri ekrandaki ham değeri yaz.
const int KURU_HAM = 3500;   // havada (kuru) okunan değer
const int ISLAK_HAM = 1500;  // suda (ıslak) okunan değer
const int KURU_YUZDE = 30;   // toprak nemi bunun altına inince sula

const unsigned long OLCUM_ARALIGI_MS = 2000;      // sensörleri 2 saniyede bir oku
const unsigned long SULAMA_MS = 5000;             // pompa çalışma süresi
const unsigned long EN_AZ_ARALIK_MS = 60000UL;    // iki otomatik sulama arası en az 1 dakika

// Çoğu röle modülü LOW ile çeker. Seninki HIGH ile çekiyorsa bu iki satırı değiştir.
const int ROLE_ACIK = LOW;
const int ROLE_KAPALI = HIGH;

Adafruit_SSD1306 ekran(128, 64, &Wire, -1);
DHT dht(DHT_PIN, DHT22);
WebServer sunucu(80);

float sicaklik = NAN;
float havaNemi = NAN;
int toprakNemi = 0;           // yüzde
bool pompaCalisiyor = false;
unsigned long pompaBaslangic = 0;
unsigned long sonSulama = 0;
bool hicSulanmadi = true;
unsigned long sonOlcum = 0;

void pompaAc() {
  if (pompaCalisiyor) return;
  pompaCalisiyor = true;
  pompaBaslangic = millis();
  digitalWrite(ROLE_PIN, ROLE_ACIK);
  Serial.println("Pompa calisiyor.");
}

void pompaKapat() {
  pompaCalisiyor = false;
  sonSulama = millis();
  hicSulanmadi = false;
  digitalWrite(ROLE_PIN, ROLE_KAPALI);
  Serial.println("Pompa durdu.");
}

void olc() {
  sicaklik = dht.readTemperature();
  havaNemi = dht.readHumidity();
  int ham = analogRead(TOPRAK_PIN);
  toprakNemi = constrain(map(ham, KURU_HAM, ISLAK_HAM, 0, 100), 0, 100);
  Serial.printf("Sicaklik: %.1f C  Nem: %.0f %%  Toprak ham: %d  Toprak: %d %%\n", sicaklik, havaNemi, ham, toprakNemi);
}

void ekranCiz() {
  ekran.clearDisplay();
  ekran.setTextSize(1);
  ekran.setCursor(0, 0);
  ekran.println("Akilli sera");
  ekran.setCursor(0, 14);
  ekran.printf("Sicaklik: %.1f C\n", sicaklik);
  ekran.setCursor(0, 26);
  ekran.printf("Hava nemi: %.0f %%\n", havaNemi);
  ekran.setCursor(0, 38);
  ekran.printf("Toprak: %d %%\n", toprakNemi);
  ekran.setCursor(0, 50);
  if (pompaCalisiyor) ekran.println("POMPA CALISIYOR");
  else ekran.println(WiFi.localIP().toString());
  ekran.display();
}

String sayfa() {
  String s = "<!doctype html><html><head><meta charset='utf-8'>";
  s += "<meta name='viewport' content='width=device-width,initial-scale=1'>";
  s += "<meta http-equiv='refresh' content='5'><title>Akıllı sera</title>";
  s += "<style>body{font-family:sans-serif;text-align:center;padding:16px}";
  s += "td{padding:6px 12px;font-size:18px}table{margin:auto}";
  s += "a{display:inline-block;margin-top:16px;padding:14px 32px;border-radius:10px;background:#0e8a8a;color:#fff;text-decoration:none;font-size:20px}</style>";
  s += "</head><body><h1>Akıllı sera</h1><table>";
  s += "<tr><td>Sıcaklık</td><td><b>" + String(sicaklik, 1) + " °C</b></td></tr>";
  s += "<tr><td>Hava nemi</td><td><b>" + String(havaNemi, 0) + " %</b></td></tr>";
  s += "<tr><td>Toprak nemi</td><td><b>" + String(toprakNemi) + " %</b></td></tr>";
  s += "<tr><td>Pompa</td><td><b>";
  s += pompaCalisiyor ? "ÇALIŞIYOR" : "duruyor";
  s += "</b></td></tr></table><a href='/sula'>Sula</a>";
  s += "<p>Sayfa 5 saniyede bir yenilenir.</p></body></html>";
  return s;
}

void anaSayfa() {
  sunucu.send(200, "text/html", sayfa());
}

void elleSula() {
  pompaAc();  // elle sulamada bekleme süresine bakılmaz
  sunucu.sendHeader("Location", "/");
  sunucu.send(303);
}

void setup() {
  Serial.begin(115200);
  pinMode(ROLE_PIN, OUTPUT);
  digitalWrite(ROLE_PIN, ROLE_KAPALI);
  dht.begin();
  Wire.begin(21, 22);
  ekran.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  ekran.setTextColor(SSD1306_WHITE);
  ekran.clearDisplay();
  ekran.setCursor(0, 0);
  ekran.println("Wi-Fi baglaniyor...");
  ekran.display();

  WiFi.mode(WIFI_STA);
  WiFi.begin(AG_ADI, PAROLA);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("Tarayicida ac: http://");
  Serial.println(WiFi.localIP());

  sunucu.on("/", anaSayfa);
  sunucu.on("/sula", elleSula);
  sunucu.begin();
}

void loop() {
  sunucu.handleClient();

  if (millis() - sonOlcum >= OLCUM_ARALIGI_MS) {
    sonOlcum = millis();
    olc();
    bool beklemeBitti = hicSulanmadi || millis() - sonSulama > EN_AZ_ARALIK_MS;
    if (!pompaCalisiyor && toprakNemi < KURU_YUZDE && beklemeBitti) {
      Serial.println("Toprak kuru: otomatik sulama.");
      pompaAc();
    }
    ekranCiz();
  }

  if (pompaCalisiyor && millis() - pompaBaslangic >= SULAMA_MS) {
    pompaKapat();
    ekranCiz();
  }
  delay(10);
}
